/*
 * Type scale, canonical excerpt. Tokens live in the installed theme; this is the docs-facing font-size-only slice.
 * ONE rung per size by ROLE — only source of font-size; never text-[Npx] or Tailwind's text-xs/sm defaults. Paired --line-height/--font-weight ride along per rung.
 */
@theme {
  /* Body/UI family: 10-16px band, ~95% of interface text; line-height stays a utility (leading-*) for per-surface density. */
  --text-micro: 0.625rem; /* 10px — kbd, badge counters, dense numeric meta */
  --text-caption: 0.6875rem; /* 11px — overlines, timestamps, section / group labels */
  --text-label: 0.75rem; /* 12px — form labels + small chrome (nav item, tooltip, shortcut) */
  --text-body: 0.875rem; /* 14px — DEFAULT body & control text (the workhorse) */
  --text-body-lg: 1rem; /* 16px — emphasized / larger body */

  /* Heading family: HIERARCHY, numbered (heading-1=largest); each pairs line-height+weight so `text-heading-N`
     carries all three, letting a skin retune headings by re-valuing these alone. */
  --text-heading-4: 0.9375rem; /* 15px */
  --text-heading-4--line-height: 1.4;
  --text-heading-4--font-weight: 600;
  --text-heading-3: 1.125rem; /* 18px */
  --text-heading-3--line-height: 1.35;
  --text-heading-3--font-weight: 600;
  --text-heading-2: 1.375rem; /* 22px */
  --text-heading-2--line-height: 1.25;
  --text-heading-2--font-weight: 600;
  --text-heading-1: 1.875rem; /* 30px — content h1 */
  --text-heading-1--line-height: 1.15;
  --text-heading-1--font-weight: 700;
  --text-heading-1--letter-spacing: -0.01em;

  /* display — the biggest rung, above the content h1: page titles (PageHeader) and heroes. */
  --text-display: 2.25rem; /* 36px */
  --text-display--line-height: 1.1;
  --text-display--font-weight: 600;
  --text-display--letter-spacing: -0.02em;

  /* Font ROLES: body+display default to --font-sans; brand re-values ONE token for headings(font-display)/body(font-body)
     own face. */
  --font-body: var(--font-sans);
  --font-display: var(--font-sans);
}

/*
 * Heading rungs also carry the display face and balanced wrapping (Tailwind merges this into the same `text-heading-N` class),
 * so a heading is ONE class: `text-heading-2`, never `text-heading-2 font-display text-balance font-semibold`.
 */
@utility text-display {
  font-family: var(--font-display);
  text-wrap: balance;
}
@utility text-heading-1 {
  font-family: var(--font-display);
  text-wrap: balance;
}
@utility text-heading-2 {
  font-family: var(--font-display);
  text-wrap: balance;
}
@utility text-heading-3 {
  font-family: var(--font-display);
  text-wrap: balance;
}
@utility text-heading-4 {
  font-family: var(--font-display);
  text-wrap: balance;
}

/*
 * History: fixed 3 competing type systems (Tailwind defaults + named rungs + raw text-[Npx]) into one rung/role; 14px = body.
 * Usage: apply the rung directly to the semantic element (no <Text> component), e.g. text-heading-1 on <h1>, text-body on <p>.
 * Heading LEVEL is the document outline; the RUNG is the look. They are decoupled on purpose: an <h3> may wear text-heading-2.
 * Control chrome text is sized by its recipe (`--cui-button-font-size`, `--cui-field-font-size`), not by these utilities.
 */

import type { ComponentProps, HTMLAttributes, Ref } from "react";

import { cn } from "@/components/control-ui/lib/cn";

const sizeClassNames = {
  display: "text-display",
  "heading-1": "text-heading-1",
  "heading-2": "text-heading-2",
  "heading-3": "text-heading-3",
  "heading-4": "text-heading-4",
  "body-lg": "text-body-lg",
  body: "text-body",
  label: "text-label",
  caption: "text-caption",
  micro: "text-micro",
} as const;

const toneClassNames = {
  default: undefined,
  foreground: "text-foreground",
  muted: "text-muted-foreground",
  primary: "text-primary-text",
  destructive: "text-destructive-text",
} as const;

const weightClassNames = {
  normal: "font-normal",
  medium: "font-medium",
  semibold: "font-semibold",
} as const;

export type TypeSize = keyof typeof sizeClassNames;
export type TypeTone = keyof typeof toneClassNames;
export type TextWeight = keyof typeof weightClassNames;
export type HeadingLevel = 1 | 2 | 3 | 4 | 5 | 6;

const headingSizeByLevel = {
  1: "heading-1",
  2: "heading-2",
  3: "heading-3",
  4: "heading-4",
  5: "heading-4",
  6: "heading-4",
} as const satisfies Record<HeadingLevel, TypeSize>;

export type HeadingProps = ComponentProps<"h1"> & { level: HeadingLevel; size?: TypeSize; weight?: TextWeight; tone?: TypeTone };

export function Heading({ level, size = headingSizeByLevel[level], weight, tone = "default", className, ...props }: HeadingProps) {
  const Tag: `h${HeadingLevel}` = `h${level}`;
  return (
    <Tag
      data-control-ui="typography"
      data-control-family="typography"
      data-slot="heading"
      className={cn(sizeClassNames[size], weight ? weightClassNames[weight] : undefined, toneClassNames[tone], className)}
      {...props}
    />
  );
}

export type TextTag =
  | "p"
  | "span"
  | "div"
  | "small"
  | "strong"
  | "em"
  | "code"
  | "li"
  | "dt"
  | "dd"
  | "figcaption"
  | "legend"
  | "blockquote";

export type TextProps = HTMLAttributes<HTMLElement> & {
  ref?: Ref<HTMLElement>;
  as?: TextTag;
  size?: TypeSize;
  weight?: TextWeight;
  tone?: TypeTone;
};

// Each tag's element type narrows the ref type; a callback ref is contravariant so it fits every tag in the union.
function attachRef(ref: Ref<HTMLElement> | undefined, node: HTMLElement | null) {
  if (typeof ref === "function") return ref(node);
  if (ref) ref.current = node;
}

export function Text({ as: Tag = "span", size = "body", weight, tone = "default", className, ref, ...props }: TextProps) {
  return (
    <Tag
      ref={ref ? (node: HTMLElement | null) => attachRef(ref, node) : undefined}
      data-control-ui="typography"
      data-control-family="typography"
      data-slot="text"
      className={cn(sizeClassNames[size], weight ? weightClassNames[weight] : undefined, toneClassNames[tone], className)}
      {...props}
    />
  );
}
